import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY")!;
const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    // Auth check
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) throw new Error("No auth header");

    const token = authHeader.replace("Bearer ", "");
    const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
    const user = { id: claimsData.claims.sub as string };

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    const { job_id } = await req.json();
    if (!job_id) throw new Error("Missing job_id");

    // Verify ownership and fetch JD
    const { data: job } = await supabase
      .from("jobs")
      .select("id, job_description, user_id")
      .eq("id", job_id)
      .single();

    if (!job) throw new Error("Job not found");
    if (job.user_id !== user.id) throw new Error("Unauthorized");

    const jdText: string = job.job_description || "";

    // Guard: refuse if JD is too short
    if (jdText.trim().length < 50) {
      throw new Error("Job description is too short to rewrite (minimum 50 characters).");
    }

    // Deduct 1 credit before calling OpenAI
    const { error: deductError } = await supabase.rpc("deduct_credits", {
      p_user_id: user.id,
      p_amount: 1,
    });
    if (deductError) throw new Error("Insufficient credits or failed to deduct credits.");

    // Single LLM call: rewrite + score the original JD
    const systemPrompt = `You are an expert technical recruiter and job description specialist. Your task is to:
1. Rewrite the provided job description for maximum clarity, ATS optimization, and inclusive language.
2. Score the ORIGINAL job description (before rewriting) on 4 dimensions.
3. Identify important keywords and whether they appear in the original.

REWRITING GUIDELINES:
- Use clear, concise language. Avoid jargon unless it is a required technical term.
- Structure with clear sections: Role Summary, Responsibilities, Requirements (Must-Have), Nice to Have, and Benefits (if present).
- Use inclusive language: avoid gendered words, age indicators, or unnecessarily exclusionary phrasing.
- Ensure ATS-friendly formatting: use standard section headers, bullet points, and spell out acronyms on first use.
- Preserve all original requirements — do not add or remove skills/qualifications.
- Keep the same general tone (technical, professional, etc.) as the original.

SCORING GUIDELINES (score the ORIGINAL JD, 0–100 each):
- clarity: How clearly written and structured is the JD? (0=incomprehensible, 100=extremely clear)
- keywords: How well does the JD include relevant industry keywords for ATS? (0=almost none, 100=comprehensive)
- ats_fit: How well formatted is the JD for ATS systems? (0=very poor, 100=excellent)
- inclusivity: How inclusive and bias-free is the language? (0=highly exclusive, 100=fully inclusive)

MISSING KEYWORDS: List 8–12 important keywords/skills. For each, indicate if it was "detected" in the original JD or "missing".

Return ONLY valid JSON with this exact structure:
{
  "rewritten_jd": "...",
  "quality_score": {
    "overall": <number 0-100, average of the 4 scores>,
    "clarity": <number 0-100>,
    "keywords": <number 0-100>,
    "ats_fit": <number 0-100>,
    "inclusivity": <number 0-100>
  },
  "missing_keywords": [
    { "keyword": "...", "status": "missing" | "detected" }
  ]
}`;

    const response = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${OPENAI_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "gpt-4o",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: `JOB DESCRIPTION TO ANALYZE AND REWRITE:\n\n${jdText.slice(0, 8000)}` },
        ],
        response_format: { type: "json_object" },
        temperature: 0.3,
      }),
    });

    if (!response.ok) {
      const errBody = await response.text();
      throw new Error(`OpenAI API error ${response.status}: ${errBody.slice(0, 200)}`);
    }

    const aiData = await response.json();
    const content = aiData.choices?.[0]?.message?.content;
    if (!content) throw new Error("OpenAI returned empty response");

    const parsed = JSON.parse(content);

    if (!parsed.rewritten_jd || !parsed.quality_score || !Array.isArray(parsed.missing_keywords)) {
      throw new Error("Unexpected response structure from OpenAI");
    }

    // Store results in jobs table
    const { error: updateError } = await supabase
      .from("jobs")
      .update({
        rewritten_jd: parsed.rewritten_jd,
        jd_quality_score: parsed.quality_score,
      } as any)
      .eq("id", job_id);

    if (updateError) throw new Error(`Failed to save rewrite results: ${updateError.message}`);

    console.log(`JD rewrite complete for job ${job_id}`);

    return new Response(
      JSON.stringify({
        success: true,
        rewritten_jd: parsed.rewritten_jd,
        quality_score: parsed.quality_score,
        missing_keywords: parsed.missing_keywords,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (err) {
    console.error("rewrite-jd error:", err);
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Loader2, Sparkles, CheckCircle2, XCircle } from "lucide-react";
import { cn } from "@/lib/utils";

interface QualityScore {
  overall: number;
  clarity: number;
  keywords: number;
  ats_fit: number;
  inclusivity: number;
}

interface MissingKeyword {
  keyword: string;
  status: "missing" | "detected";
}

interface RewriteResult {
  rewritten_jd: string;
  quality_score: QualityScore;
  missing_keywords: MissingKeyword[];
}

interface JDRewriteDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  jobId: string;
  originalJd: string;
  onApply: (newJd: string) => void;
}

const SCORE_LABELS: { key: keyof Omit<QualityScore, "overall">; label: string }[] = [
  { key: "clarity", label: "Clarity" },
  { key: "keywords", label: "Keywords" },
  { key: "ats_fit", label: "ATS Fit" },
  { key: "inclusivity", label: "Inclusivity" },
];

function scoreColor(score: number): string {
  if (score >= 75) return "bg-green-500";
  if (score >= 50) return "bg-yellow-500";
  return "bg-red-500";
}

function scoreTextColor(score: number): string {
  if (score >= 75) return "text-green-600";
  if (score >= 50) return "text-yellow-600";
  return "text-red-600";
}

const JDRewriteDialog = ({ open, onOpenChange, jobId, originalJd, onApply }: JDRewriteDialogProps) => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<RewriteResult | null>(null);
  const [editedJd, setEditedJd] = useState("");

  const handleRewrite = async () => {
    setLoading(true);
    setResult(null);
    try {
      const { data, error } = await supabase.functions.invoke("rewrite-jd", {
        body: { job_id: jobId },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      setResult(data as RewriteResult);
      setEditedJd(data.rewritten_jd);
      toast.success("JD rewrite complete");
    } catch (err: any) {
      toast.error(err?.message || "Failed to rewrite JD");
    } finally {
      setLoading(false);
    }
  };

  const handleApply = () => {
    if (!editedJd.trim()) return;
    onApply(editedJd);
    onOpenChange(false);
    toast.success("Rewritten JD applied");
  };

  const handleClose = () => {
    if (loading) return;
    onOpenChange(false);
  };

  const handleOpenChange = (nextOpen: boolean) => {
    if (!nextOpen && loading) return;
    if (!nextOpen) {
      // Reset state when closing
      setResult(null);
      setEditedJd("");
    }
    onOpenChange(nextOpen);
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-5xl w-full max-h-[90vh] overflow-hidden flex flex-col">
        <DialogHeader className="shrink-0">
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-primary" />
            AI Rewrite JD
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto min-h-0">
          {!result && !loading && (
            <div className="flex flex-col items-center justify-center py-12 gap-4 text-center">
              <div className="w-14 h-14 rounded-full bg-primary/10 flex items-center justify-center">
                <Sparkles className="h-7 w-7 text-primary" />
              </div>
              <div>
                <p className="font-semibold text-base mb-1">Rewrite for Clarity &amp; ATS Optimization</p>
                <p className="text-sm text-muted-foreground max-w-sm">
                  AI will rewrite your JD for clarity and inclusivity, score its quality on 4 dimensions, and identify missing keywords.
                  Costs 1 credit.
                </p>
              </div>
              <Button onClick={handleRewrite} className="gap-2">
                <Sparkles className="h-4 w-4" />
                Rewrite JD
              </Button>
            </div>
          )}

          {loading && (
            <div className="flex flex-col items-center justify-center py-16 gap-3">
              <Loader2 className="h-8 w-8 text-primary animate-spin" />
              <p className="text-sm text-muted-foreground">Analyzing and rewriting your JD…</p>
            </div>
          )}

          {result && (
            <div className="space-y-6 pb-4">
              {/* Two-column JD side by side */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="flex flex-col gap-2">
                  <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Original JD</p>
                  <Textarea
                    readOnly
                    value={originalJd}
                    className="min-h-[280px] resize-none text-sm bg-muted/40 cursor-default"
                  />
                </div>
                <div className="flex flex-col gap-2">
                  <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                    Rewritten JD
                    <span className="ml-2 text-[10px] normal-case font-normal text-muted-foreground">(editable)</span>
                  </p>
                  <Textarea
                    value={editedJd}
                    onChange={(e) => setEditedJd(e.target.value)}
                    className="min-h-[280px] resize-none text-sm"
                  />
                </div>
              </div>

              {/* Quality Score */}
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <p className="text-sm font-semibold">Quality Score (Original)</p>
                  <span className={cn("text-sm font-bold", scoreTextColor(result.quality_score.overall))}>
                    {result.quality_score.overall}/100
                  </span>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {SCORE_LABELS.map(({ key, label }) => {
                    const score = result.quality_score[key];
                    return (
                      <div key={key} className="space-y-1">
                        <div className="flex items-center justify-between text-xs">
                          <span className="text-muted-foreground">{label}</span>
                          <span className={cn("font-medium", scoreTextColor(score))}>{score}</span>
                        </div>
                        <div className="h-2 rounded-full bg-muted overflow-hidden">
                          <div
                            className={cn("h-full rounded-full transition-all duration-500", scoreColor(score))}
                            style={{ width: `${score}%` }}
                          />
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              {/* Missing Keywords */}
              {result.missing_keywords.length > 0 && (
                <div className="space-y-2">
                  <p className="text-sm font-semibold">Keyword Analysis</p>
                  <div className="flex flex-wrap gap-2">
                    {result.missing_keywords.map((kw) => (
                      <Badge
                        key={kw.keyword}
                        variant="outline"
                        className={cn(
                          "gap-1 text-xs",
                          kw.status === "detected"
                            ? "border-green-500/50 text-green-700 bg-green-50 dark:text-green-400 dark:bg-green-950/30"
                            : "border-red-500/50 text-red-700 bg-red-50 dark:text-red-400 dark:bg-red-950/30"
                        )}
                      >
                        {kw.status === "detected" ? (
                          <CheckCircle2 className="h-3 w-3" />
                        ) : (
                          <XCircle className="h-3 w-3" />
                        )}
                        {kw.keyword}
                      </Badge>
                    ))}
                  </div>
                  <p className="text-[11px] text-muted-foreground">
                    <span className="inline-flex items-center gap-1 text-green-600"><CheckCircle2 className="h-3 w-3" /> Detected</span>
                    {" "}in original JD.{" "}
                    <span className="inline-flex items-center gap-1 text-red-600"><XCircle className="h-3 w-3" /> Missing</span>
                    {" "}from original JD.
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter className="shrink-0 border-t pt-4 mt-2 gap-2">
          {result && (
            <Button variant="outline" onClick={handleRewrite} disabled={loading} className="gap-2">
              {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Sparkles className="h-4 w-4" />}
              Regenerate
            </Button>
          )}
          <Button variant="ghost" onClick={handleClose} disabled={loading}>
            Discard
          </Button>
          {result && (
            <Button onClick={handleApply} disabled={!editedJd.trim() || loading} className="gap-2">
              <CheckCircle2 className="h-4 w-4" />
              Apply Rewrite
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default JDRewriteDialog;

